// Kiểm tra dữ liệu WordPress gửi sang và chuẩn bị câu trả lời.
// Mọi tín hiệu kiểm tra được giữ lại trong output để xem ở tab Executions.
const receivedAt = new Date().toISOString();
const input = $input.first().json;
const body = input.body ?? {};
const headers = input.headers ?? {};
const executionId = $execution.id;
const requestId = body.request_id ?? headers['x-socialsync-request-id'] ?? null;

const trace = {
  received_at: receivedAt,
  request_id: requestId,
  plugin_version: headers['x-socialsync-version'] ?? null,
  content_type: headers['content-type'] ?? null,
  event: body.event ?? null,
};

if (body.event === 'test') {
  return [{ json: {
    http_status: 200,
    response: { ok: true, test: true, execution_id: executionId, request_id: requestId, received_at: receivedAt },
    trace,
    data: body,
  } }];
}

const problems = [];
const need = (cond, msg) => { if (!cond) problems.push(msg); };
const jobs = Array.isArray(body.jobs) ? body.jobs : [];

need(body.event === 'post_published', `event không hợp lệ: ${JSON.stringify(body.event)}`);
need(Number.isInteger(body.post_id) && body.post_id > 0, 'thiếu hoặc sai post_id');
need(['post', 'product'].includes(body.post_type), `post_type không hỗ trợ: ${JSON.stringify(body.post_type)}`);
need(typeof body.title === 'string' && body.title.trim() !== '', 'thiếu title');
need(typeof body.source_url === 'string' && /^https?:\/\//.test(body.source_url), 'thiếu hoặc sai source_url');
need(typeof body.callback_url === 'string' && /^https?:\/\//.test(body.callback_url), 'thiếu hoặc sai callback_url');
need(jobs.length > 0, 'không có lượt đồng bộ nào (jobs rỗng)');
for (const j of jobs) {
  need(Number.isInteger(j.job_id) && j.job_id > 0, `lượt thiếu job_id: ${JSON.stringify(j)}`);
  need(['facebook', 'pinterest'].includes(j.channel), `kênh không hỗ trợ: ${JSON.stringify(j.channel)}`);
}

const signals = {
  post_type: body.post_type ?? null,
  channels: jobs.map(j => j.channel),
  delays_minutes: Object.fromEntries(jobs.map(j => [j.channel, j.delay_minutes ?? 0])),
  has_image: Boolean(body.image_url),
  image_size: body.image ? `${body.image.width}x${body.image.height}` : null,
  title_chars: (body.title ?? '').length,
  content_chars: (body.content_text ?? '').length,
  excerpt_chars: (body.excerpt ?? '').length,
  categories: body.categories ?? [],
  has_price: Boolean(body.price && body.price.price),
  pinterest_will_skip: jobs.some(j => j.channel === 'pinterest') && !body.image_url,
};

if (problems.length) {
  return [{ json: {
    http_status: 422,
    response: { ok: false, execution_id: executionId, request_id: requestId, error: problems.join('; ') },
    problems,
    signals,
    trace,
    data: body,
  } }];
}

return [{ json: {
  http_status: 202,
  response: {
    ok: true,
    execution_id: executionId,
    request_id: requestId,
    received_at: receivedAt,
    accepted_jobs: jobs.map(j => j.job_id),
  },
  signals,
  trace,
  data: body,
} }];

// Nấc 2: tách mỗi lượt (kênh) thành một item và dựng nội dung theo MẪU CỐ ĐỊNH (chưa dùng AI).
// Chỉ chạy tiếp khi bước kiểm tra đã nhận bài (HTTP 202). Gói test hoặc dữ liệu lỗi dừng ở đây.
const CONFIG = {
  fb_page_id: '273106486233478',   // Fanpage Mint Shop - facebook.com/myphamcuatrang (ID công khai, không phải bí mật)
  graph_version: 'v21.0',
  utm_campaign: 'socialsync',
  fb_summary_max: 400,
  pin_title_max: 100,
  pin_description_max: 400,
};

const checked = $('Kiểm tra dữ liệu').first().json;
if (checked.http_status !== 202) {
  return [];
}
const d = checked.data;

// Môi trường Code của n8n 2.x không có đối tượng URL (đo 2026-11-19: ReferenceError: URL is not defined),
// nên gắn tham số UTM bằng xử lý chuỗi.
const withUtm = (url, source) => {
  const hashAt = url.indexOf('#');
  const base = hashAt === -1 ? url : url.slice(0, hashAt);
  const hash = hashAt === -1 ? '' : url.slice(hashAt);
  const utm = `utm_source=${encodeURIComponent(source)}&utm_medium=social&utm_campaign=${encodeURIComponent(CONFIG.utm_campaign)}`;
  return base + (base.includes('?') ? '&' : '?') + utm + hash;
};

// Cắt ở ranh giới câu nếu được, nếu không thì ở ranh giới từ. Không cắt giữa từ.
const clip = (text, max) => {
  const t = String(text ?? '').replace(/\s+/g, ' ').trim();
  if (t.length <= max) return t;
  const cut = t.slice(0, max);
  const sentenceEnd = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));
  if (sentenceEnd > max * 0.5) return cut.slice(0, sentenceEnd + 1);
  return cut.slice(0, Math.max(cut.lastIndexOf(' '), 1)) + '…';
};

const summary = clip(d.excerpt || d.content_text, CONFIG.fb_summary_max);
const priceLine = d.price && d.price.price_text ? `Giá: ${d.price.price_text}` : null;
const now = Date.now();

return d.jobs.map(job => {
  const link = withUtm(d.source_url, job.channel);
  let content;
  let facebook = null;

  if (job.channel === 'facebook') {
    const message = [d.title, summary, priceLine, `👉 Xem chi tiết: ${link}`].filter(Boolean).join('\n\n');
    content = { kind: d.image_url ? 'photo' : 'link', message, link, image_url: d.image_url || null };
    facebook = d.image_url
      ? { url: `https://graph.facebook.com/${CONFIG.graph_version}/${CONFIG.fb_page_id}/photos`, body: { url: d.image_url, caption: message, published: true } }
      : { url: `https://graph.facebook.com/${CONFIG.graph_version}/${CONFIG.fb_page_id}/feed`, body: { message, link } };
  } else {
    content = {
      title: clip(d.title, CONFIG.pin_title_max),
      description: clip([summary, priceLine].filter(Boolean).join(' '), CONFIG.pin_description_max),
      alt_text: d.image_alt || d.title,
      link,
      image_url: d.image_url || null,
    };
  }

  const delaySeconds = Math.max(0, Math.round(Number(job.delay_minutes ?? 0) * 60));
  return {
    json: {
      job_id: job.job_id,
      channel: job.channel,
      post_id: d.post_id,
      post_type: d.post_type,
      title: d.title,
      request_id: d.request_id ?? null,
      has_image: Boolean(d.image_url),
      delay_seconds: delaySeconds,
      scheduled_at: new Date(now + delaySeconds * 1000).toISOString(),
      callback_job_url: `${d.callback_url}/${job.job_id}`,
      content_source: 'template',
      content_source_reason: 'Nấc 2: chưa bật AI, dùng mẫu cố định',
      content,
      facebook,
    },
  };
});

// Chỉ đăng những lượt WordPress đã chấp nhận chuyển sang "scheduled".
// WordPress từ chối (ví dụ 409: lượt đã xử lý rồi) => dừng lượt đó, KHÔNG đăng, tránh đăng trùng.
const source = $('Tách lượt và dựng nội dung').all();
const out = [];
$input.all().forEach((item, i) => {
  const s = source[i].json;
  const r = item.json;
  const ok = r.statusCode === 200 && r.body && r.body.ok === true;
  if (ok) {
    out.push({ json: { ...s, wp_scheduled: { statusCode: r.statusCode, body: r.body } }, pairedItem: { item: i } });
  } else {
    console.log(`[socialsync] Dừng lượt ${s.job_id} (${s.channel}): WordPress không chấp nhận`, JSON.stringify({ statusCode: r.statusCode ?? null, body: r.body ?? null, error: r.error ?? null }));
  }
});
return out;

// Đọc phản hồi của Facebook, chuẩn bị dữ liệu báo về WordPress.
// Mỗi bài chỉ gọi Facebook đúng 1 lần để tiết kiệm hạn mức API của app.
const s = $('Kênh Facebook?').item.json;
const r = $json;

let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* giữ nguyên chuỗi */ } }
const headers = r.headers ?? {};
// Facebook trả % hạn mức đã dùng trong các header này (app, Trang, doanh nghiệp).
const usage = {
  app: headers['x-app-usage'] ?? null,
  page: headers['x-page-usage'] ?? null,
  business: headers['x-business-use-case-usage'] ?? null,
};

let callback;
if (r.error && r.statusCode === undefined) {
  callback = { status: 'failed', error: `Không gọi được Facebook: ${r.error.message ?? JSON.stringify(r.error)}` };
} else if (r.statusCode >= 200 && r.statusCode < 300 && body && (body.post_id || body.id)) {
  const postId = body.post_id ?? body.id;
  callback = {
    status: 'published',
    remote_id: String(postId),
    remote_url: `https://www.facebook.com/${postId}`,
    // Bài đăng bởi app ở chế độ Live lên Trang công khai. Đã kiểm tra bằng cửa sổ ẩn danh ở lần test đầu.
    visibility: 'public',
    published_at: new Date().toISOString(),
  };
} else {
  const e = (body && body.error) || {};
  const rateLimited = [4, 17, 32, 613, 80001].includes(Number(e.code));
  callback = {
    status: 'failed',
    error: `Facebook từ chối (HTTP ${r.statusCode}${e.code ? `, mã ${e.code}` : ''}${e.error_subcode ? `/${e.error_subcode}` : ''}${rateLimited ? ', HẾT HẠN MỨC GỌI API' : ''}): ${e.message ?? JSON.stringify(body)}${e.fbtrace_id ? ` [fbtrace_id ${e.fbtrace_id}]` : ''}`,
  };
}
callback.execution_id = $execution.id;

return { json: { ...s, callback, facebook_result: { statusCode: r.statusCode ?? null, body, usage } } };

// Nấc 3 sẽ thay khối này bằng bước tạo Pin thật.
const s = $json;
const reason = s.has_image ? 'Kênh Pinterest chưa được cấu hình (làm ở nấc 3)' : 'Bài không có ảnh đại diện, Pinterest bắt buộc có ảnh';
return { json: { ...s, callback: { status: 'skipped', error: reason, execution_id: $execution.id } } };
